# Check what ground_res and rgbd_res actually returned in turn 4
def find_handles(d):
    handles = []
    if isinstance(d, dict):
        for k, v in d.items():
            if "handle" in str(k) and isinstance(v, str):
                handles.append(v)
            elif "handle" in str(k) and isinstance(v, list):
                for item in v:
                    if isinstance(item, str):
                        handles.append(item)
            elif isinstance(v, (dict, list)):
                handles.extend(find_handles(v))
    elif isinstance(d, list):
        for item in d:
            handles.extend(find_handles(item))
    return handles


